def safe_status(task):
    s=task.get("status")
    return s.get("status") if isinstance(s,dict) else None

def safe_priority(task):
    p=task.get("priority")
    return p.get("priority") if isinstance(p,dict) else None

def to_row(task):
    return {"id":task.get("id"),"name":task.get("name"),"status":safe_status(task),"priority":safe_priority(task)}
